export function useGetWebhookStatus<TData = Awaited<ReturnType<typeof getWebhookStatus>>, TError = ErrorType<unknown>>(
  options?: { query?:UseQueryOptions<Awaited<ReturnType<typeof getWebhookStatus>>, TError, TData>, request?: SecondParameter<typeof customFetch>}

 ):  UseQueryResult<TData, TError> & { queryKey: QueryKey } {

  const queryOptions = getGetWebhookStatusQueryOptions(options)

  const query = useQuery(queryOptions) as  UseQueryResult<TData, TError> & { queryKey: QueryKey };

  return withQueryKey(query, queryOptions.queryKey);
}







export const getResetWebhookUrl = () => {




  return `/api/admin/webhook/reset`
}

/**
 * @summary Reset the Telegram bot webhook
 */
export const resetWebhook = async ( options?: RequestInit): Promise<WebhookStatus> => {

  return customFetch<WebhookStatus>(getResetWebhookUrl(),
  {
    ...options,
    method: 'POST'


  }
);}





export const getResetWebhookMutationOptions = <TError = ErrorType<unknown>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof resetWebhook>>, TError,void, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof resetWebhook>>, TError,void, TContext> => {

const mutationKey = ['resetWebhook'];
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof resetWebhook>>, void> = () => {


          return  resetWebhook(requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type ResetWebhookMutationResult = NonNullable<Awaited<ReturnType<typeof resetWebhook>>>

    export type ResetWebhookMutationError = ErrorType<unknown>

    /**
 * @summary Reset the Telegram bot webhook
 */
export const useResetWebhook = <TError = ErrorType<unknown>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof resetWebhook>>, TError,void, TContext>, request?: SecondParameter<typeof customFetch>}
 ): UseMutationResult<
        Awaited<ReturnType<typeof resetWebhook>>,
        TError,
        void,
        TContext
      > => {
      return useMutation(getResetWebhookMutationOptions(options));
    }

